                    'status': 'healthy' if github_healthy else 'error',
                    'repository': self.github_repo
                }
            except Exception as e:
                report['integrations']['github'] = {
                    'status': 'error',
                    'error': str(e)
                }
        else:
            report['integrations']['github'] = {
                'status': 'no_token',
                'message': 'GitHub token not available'
            }

        # Determine overall health
        integration_statuses = [
            integration['status'] for integration in report['integrations'].values()
        ]

        if all(status == 'healthy' for status in integration_statuses):
            report['health_status'] = 'healthy'
        elif any(status == 'healthy' for status in integration_statuses):
            report['health_status'] = 'degraded'
        else:
            report['health_status'] = 'error'

        return report

